#include <stdio.h>

struct Row {
  int cells[2];
};

static void set_cell(struct Row *row) {
  row->cells[1] = 9;
}

static int *mutable_identity(const int *value) { return (int *)value; }

int main(void) {
  struct Row row = {{3, 4}};
  set_cell(&row);
  int value                 = 7;
  *mutable_identity(&value) = 11;
  printf("%d %d\n", row.cells[1], value);
  return 0;
}



